import math


def sharpe_ratio(returns, rf=0.0, periods=252):
    # Excess return each period over the risk-free rate
    xs = [r - rf / periods for r in returns]
    n = len(xs)
    if n < 2:
        return None
    mean = sum(xs) / n
    var = sum((x - mean) ** 2 for x in xs) / (n - 1)
    if var == 0:
        return None
    return mean / math.sqrt(var) * math.sqrt(periods)
